function [ type ] = checkPropertyName( name )
%CHECKPROPERTYNAME Checks, if a variable name is valid
%   All variables which should be used in the program have to be defined
%   here.
%
%   Author: Dr. Quirin Aumann (https://qaumann.github.io/)
%   Part of bm-mfem, Chair of Structural Mechanics, Technical University
%   of Munich.

availableProperties = ["ELEMENTAL_STIFFNESS", ...
    "ELEMENTAL_DAMPING", ...
    "ELEMENTAL_MASS", ...
    "IY", ...
    "IZ", ...
    "IT", ...
    "YOUNGS_MODULUS", ...
    "POISSON_RATIO", ...
    "CROSS_SECTION", ...
    "THICKNESS", ...
    "NUMBER_GAUSS_POINT", ... 
    "SHEAR_CORRECTION_FACTOR",...
    "DENSITY", ...
    "STEP", ...
    "TIME", ...
    "RAYLEIGH_ALPHA", ...
    "RAYLEIGH_BETA", ...
    "YOUNGS_MODULUS_HS", ...
    "POISSON_RATIO_HS", ...
    "DENSITY_HS", ...
    "ELEMENTAL_DAMPING_HS", ...
    "SAMPLE_NUMBER_X", ...
    "SAMPLE_RATE_X", ...
    "SPEED_OF_SOUND",...
    "DENSITY_FLUID",...
    "DENSITY_SOLID",...
    "LAMBDA_SOLID", ...
    "MUE_SOLID", ...
    "DAMPING_SOLID", ...
    "VISCOSITY_FLUID", ...
    "STANDARD_PRESSURE_FLUID", ...
    "HEAT_CAPACITY_FLUID", ...
    "PRANDTL_NUMBER_FLUID", ...
    "POROSITY", ...
    "TORTUOSITY", ...
    "FLOW_RESISTIVITY", ...
    "VISCOUS_LENGHT", ...
    "THERMAL_LENGTH", ...
    "FREQUENCY",...
    "VELOCITY",...
    "NORMAL_DISPLACEMENT",...
    "ADMITTANCE",...
    "IS_COUPLING_NODE",...
    "DIRECTION",...
    "SURFACE_DENSITY",...
    "RATIO_OLD_NEW",...
    "NT",...
    "CALC_SYSTEM",...
    "CALC_LOADTYPE",...
    "SAMPLE_NUMBER_Y", ...
    "SAMPLE_RATE_Y",...
    "FCENTROIDS",...
    "B_F",...
    "L_F",...
    "B_FLEX", ...
    "L_FLEX",...
    "STIFF_SOIL",...
    "RELAXED_BC"];

available3dProperties = ["VOLUME_ACCELERATION", ...
    "POINT_LOAD"];

availableMatrixProperties = ["STRESS_TENSOR"];

availableFlags = ["FULL_INTEGRATION", ...
    "USE_CONSISTENT_MASS_MATRIX", ...
    "USE_PLANE_STRAIN"];

availableScalarDofNames = ["PRESSURE", ...
    "ACOUSTIC_PRESSURE"];

availableVectorDofNames = ["DISPLACEMENT", ...
    "DISPLACEMENT_FLUID", ...
    "ROTATION"];

if any(ismember(name, availableProperties))
    type = 'variable1d';
elseif any(ismember(name, available3dProperties))
    type = 'variable3d';
elseif any(ismember(name, availableMatrixProperties))
    type = 'matrix';
elseif any(ismember(name, availableFlags))
    type = 'flag';
elseif any(ismember(name, availableScalarDofNames))
    type = 'dofscalar';
elseif any(ismember(name, availableVectorDofNames))
    type = 'dofvec';
else
    msg = ['CheckPropertyName: A property with name \"', ...
        name, '\" is not defined'];
    e = MException('MATLAB:bm_mfem:undefinedPropertyName',msg);
    throw(e);
end

end

